\label{thm:main}
Assume
\begin{equation}\label{eq:main-range}
 n\ge3,
 \qquad
 1<q<p<\frac{n+2}{n-2}.
\end{equation}
Then, for every integer $k\ge1$, problem \eqref{eq:PDE} possesses exactly
one radial $k$-node bound state $u_k=u_k(r)$ satisfying $u_k(0)>0$.

If $u'\ne0$, let $\theta$ be the quantity defined above.
Then, wherever $u\ne0$ and $u'\ne0$,
\begin{equation}\label{eq:connection}
 Q-P\frac vu=\omega(M-\theta).
\end{equation}
Moreover, with
\[
 T_2:=Q-g_2(u)M
\]
on an interval $\lvertu\rvert>1$,
\begin{align}
 T_2'
 &=r^{n-1}g_2'(u)h_1(u)v-g_2'(u)u'M,\label{eq:T2prime-regular}\\
 &= -g_2'(u)u'(M-\theta)\quad \text{if }u'\neq0.\label{eq:T2prime}
\end{align}
Finally, wherever $u'\ne0$,
\begin{equation}\label{eq:T2B0}
 T_2=B_0+\frac{g_2(u)}{g_2'(u)u'}T_2'.
\end{equation}

\label{lem:factor}
Fix $A\ge\beta$ and put $a=g_2(A)$.  Then $F_a(\pm A)=0$ and
\begin{equation*}
 -2F_a(s)=C_A\lverts\rvert^{q+1}
 \left[1-\left(\frac{\lverts\rvert}{A}\right)^{p-q}\right],
 \qquad \lverts\rvert\le A,
\end{equation*}
where
\[
 C_A:=\frac{2-(q-1)g_2(A)}{q+1}>0.
\]

\label{lem:prep}
Assume \eqref{eq:ind-data}.  Then the first zero \eqref{eq:tau-phase} is the only zero of $v$ before $\max\{\tau,b\}$, and
\begin{equation}\label{eq:T2-prep}
 T_2,T_2'>0
 \quad\text{on }[c_-,\max\{\tau,b\}].
\end{equation}
Moreover
\begin{equation}\label{eq:Qfamily-prep}
 Q,M,  Q_1,  Q_2>0
 \quad\text{on }[c_-,\max\{\tau,b\}].
\end{equation}

\label{lem:residual-parameter}
Assume $1<q<p$ and $p+q<3$.
Then
\begin{equation}\label{eq:beta-basic-bounds}
 \beta<\sqrt e,
 \qquad
 {\beta^{q-1}(3\beta-4)<3\sqrt e-4<1.}
\end{equation}
Moreover, if
\begin{equation}\label{eq:kappa-window}
 1<\kappa<3(\beta-1),
\end{equation}
one has
\begin{equation}\label{eq:kappa-weight-bound}
 {\kappa \beta^{q-1}\bigl(3(\beta-1)-\kappa\bigr)
 <3\sqrt e-4<1.}
\end{equation}

\label{lem:residual}
Assume \eqref{eq:ind-data} and \eqref{eq:residual-range}. Consider a normalized phase with $b<\tau$.
Then for every $A\ge\beta$,
\begin{equation}\label{eq:residual-integral}
 \int_b^\tau
 u(r)^{q+1}
 \left[1-\left(\frac{u(r)}{A}\right)^{p-q}\right]
 \frac{Q_3(r)}{r u'(r)^2}\,\mathrm d r>0.
\end{equation}

\label{lem:river}
Under \eqref{eq:ind-data}, $v$ has no second zero on $[\tau,c_+]$, and
\begin{equation}\label{eq:Q12all}
 Q_1,Q_2>0\quad\text{on }[c_-,c_+].
\end{equation}
Moreover
\begin{equation}\label{eq:Qbb}
 Q(\bar b)>Q(b)>0,
 \qquad
 Q>0\quad\text{on }[c_-,\max\{\tau,b\}]\cup[\bar b,c_+].
\end{equation}

\label{lem:renewal}
Assume \eqref{eq:ind-data}.
Then $T_2(c_+)>0$.

\label{lem:tail-prep}
Assume that at $c_*$,
\begin{equation}\label{eq:tail-ind-data}
 Q(c_*)>0,\qquad M(c_*)>0,\qquad T_2(c_*)>0.
\end{equation}
Then $v$ has a unique zero $\tau_{*}$ on  $[c_*,s_{**}]$, where $s_{**}:=\max\{\tau_{*},b_{*}\}$. Moreover,
\begin{equation}\label{eq:tail-prep-conclusion}
 T_2,T_2',Q,M,Q_1,Q_2>0
 \quad\text{on }[c_*,s_{**}].
\end{equation}
